-- Erzeugt aus menu.json mit "npm run karte". Ersetzt die Karte in der Datenbank komplett durch menu.json.
begin;
  on conflict (name) do update set kategorie = excluded.kategorie, preis_cent = excluded.preis_cent, getraenk = excluded.getraenk,
    beschreibung = excluded.beschreibung, reihenfolge = excluded.reihenfolge, titel = '', name_en = '', beschreibung_en = '', versteckt = false, eigen = false;
update artikel set versteckt = true where name not in ('Café Crema', 'Americano', 'Espresso', 'Espresso Doppio', 'Espresso Macchiato', 'Cappuccino', 'Flat White', 'Milchkaffee', 'Latte Macchiato', 'Kaffee & Kuchen Deal', 'Earl Grey', 'Jasmin-Grüntee', 'Früchtetee Waldbeere', 'Frischer Minztee', 'Frischer Ingwer-Zitronentee', 'Hot Matcha', 'Iced Matcha', 'Strawberry Iced Matcha', 'Mango Iced Matcha', 'Iced Americano', 'Iced Latte', 'Iced Vanilla Latte', 'Iced Chai Latte', 'Chai Latte', 'Pumpkin Spice Latte', 'Hot Chocolate', 'Hot White Chocolate', 'Pfirsich-Limo', 'Zitronen-Minze-Holunder-Limo', 'Himbeer-Minze-Holunder-Limo', 'Maracuja-Limette-Limo', 'Frisch gepresster Orangensaft', 'Beet & Juice', 'Berry Banana', 'Green Glow', 'Mango Sunshine', 'fritz-kola 0,2 l', 'fritz-kola super zero 0,2 l', 'fritz-limo Apfel-Kirsch-Holunder 0,2 l', 'fritz-spritz Bio-Rhabarberschorle 0,2 l', 'Zurück zu den Quellen, still 0,33 l', 'Zurück zu den Quellen, sprudelnd 0,33 l', 'Apfel-Brie-Grilltoast', 'Winterburger Goat', 'Vegane Schupfnudelpfanne', 'Nannis Knusper-Rösti', 'Rührei Genuss', 'Omelett-Bar', 'Nannis Brunch-Favourite', 'Classic Açaí Bowl', 'Lotus Crunch Açaí Bowl', 'Apfel Crunch Porridge', 'Nanni Egg Drop', 'Halloumi-Honey Drop', 'Pastrami New York Style Drop', 'Burrata Italia', 'Kleine Süßkartoffel-Pommes + Dip', 'Süßkartoffel-Pancakes mit Halloumi', 'Süßkartoffel-Pancakes mit Tofu & Avocado', 'Süßkartoffel-Pancakes mit Feta', 'Avocado & Poached Egg', 'Smoky Tofu Bagel', 'Sucuk Egg Bagel', 'Egg Bagel', 'Salmon Bagel', 'Süßkartoffel-Pommes mit Dip', 'Classic French Toast', 'Classy Berry Pancakes', 'Bueno Berry Pancakes', 'Nannis Vegan Banana Bread', 'Classic Vegan', 'Banana Choc', 'Lotus Crunch', 'White Bueno Crunch', 'Heiße Liebe', 'Kirschtraum', 'Oreo Berry Banana', 'Fruchttraum');
