  ('Apfel-Brie-Grilltoast', 'lunchdeal', 1390, false, 'Knusprig getoastet, gefüllt mit Apfel, Brie und Feigensenf. Dazu Preiselbeersoße, eine kleine Portion Pommes und Salat mit Granatapfelkernen und Walnüssen, abgerundet mit Apfel-Senf-Vinaigrette.', 43),
  ('Winterburger Goat', 'lunchdeal', 1490, false, 'Brioche Bun mit Preiselbeersoße und Honig-Senf-Sauce, belegt mit Baby-Leaf-Mix, karamellisiertem Ziegenkäse, Apfel und Avocado. Dazu Pommes mit Kräuterquark.', 44),
  ('Vegane Schupfnudelpfanne', 'lunchdeal', 1290, false, 'Gebratene Kartoffel-Schupfnudeln mit Champignons in cremiger pflanzlicher Rahmsauce.', 45),
  ('Nannis Knusper-Rösti', 'lunchdeal', 1390, false, 'Kartoffelrösti mit Kräuterquark, Spiegelei, Kürbiskernen und Beilagensalat.', 46),
  ('Rührei Genuss', 'fruehstueck', 790, false, 'Cremiges Rührei, geröstetes Sauerteigbrot und Frischkäsecreme.', 47),
  ('Omelett-Bar', 'fruehstueck', 890, false, 'Frisch zubereitetes Omelett mit Brot und Frischkäsecreme – verfeinere dein Omelett mit den Extras unten.', 48),
  ('Nannis Brunch-Favourite', 'fruehstueck', 1490, false, 'Cremiges Rührei auf geröstetem Sauerteigbrot mit Avocado, Tomaten, Pickled Onions und Granatapfelkernen. Dazu zwei fluffige Pancakes mit Beeren, Soja-Vanillecreme und Bio-Ahornsirup.', 49),
  ('Classic Açaí Bowl', 'bowls', 1190, false, 'Cremige Açaí, kalt serviert mit Beeren, Banane, Crunchy Granola, Chiasamen und Kokosflocken – verfeinert mit Dattelsirup.', 50),
  ('Lotus Crunch Açaí Bowl', 'bowls', 1290, false, 'Cremige Açaí, kalt serviert mit Beeren, Banane, Crunchy Granola, Soja-Vanillecreme, Chiasamen und Kokosflocken – getoppt mit Lotus Swirl und Lotus Crumble.', 51),
  ('Apfel Crunch Porridge', 'bowls', 990, false, 'Warmes, cremiges Porridge mit Apfelkompott und Apfelstücken, Granola, gemahlenen Haselnüssen, Kokosflocken und Zimt – verfeinert mit einem Hauch Lotus Swirl.', 52),
  ('Nanni Egg Drop', 'shokupan', 1090, false, 'Goldbraun getoastet mit Topping deiner Wahl, Cheddar-Melt, fluffigem, cremigem Rührei und Avocado, dazu hausgemachter Sweet-Cream-Senf als Finish. Topping: Bacon, Sucuk, Lachs oder Tofu. Sauce: Trüffelcreme oder Sriracha-Mayo.', 53),
  ('Halloumi-Honey Drop', 'shokupan', 1290, false, 'Toskanacreme, Rucola, Halloumi, Tomaten, Honig, Kürbiskerne, Chili und Granatapfel-Drizzle.', 54),
  ('Pastrami New York Style Drop', 'shokupan', 1390, false, 'Frischkäse, Rucola, Tomaten, Pastrami, Cornichons und Käse-Melt, Dattel-Senf-Dressing und Balsamico.', 55),
  ('Burrata Italia', 'shokupan', 1390, false, 'Pesto, Rucola, Tomaten, Burrata, geröstete Pinienkerne, Olivenöl und Balsamico-Drizzle.', 56),
  ('Kleine Süßkartoffel-Pommes + Dip', 'shokupan', 390, false, 'Zu deinem Shokupan. Dip: Trüffelcreme, Kräuterquark, vegane Mayo oder Ketchup.', 57),
  ('Süßkartoffel-Pancakes mit Halloumi', 'pancakes', 1150, false, 'Belegt mit Rucola-Mix, Tomaten, Halloumi, Kürbiskernen, Chili, Balsamico und Honig. Herzhaft, süß und einfach unwiderstehlich!', 58),
  ('Süßkartoffel-Pancakes mit Tofu & Avocado', 'pancakes', 1150, false, 'Belegt mit Rucola-Mix, Tomaten, Avocado, Tofu, Granatapfelkernen und Balsamico. Frisch, nussig und voller Power!', 59),
  ('Süßkartoffel-Pancakes mit Feta', 'pancakes', 1150, false, 'Belegt mit Rucola-Mix, Feta, Tomaten, Avocado, Granatapfelkernen und Balsamico. Cremig, frisch und perfekt abgestimmt!', 60),
  ('Avocado & Poached Egg', 'bagels', 990, false, 'Frischkäse, Rucola, Tomaten, Avocado, pochiertes Ei und Sweet-Cream-Senf-Drizzle.', 61),
  ('Smoky Tofu Bagel', 'bagels', 990, false, 'Frischkäse, Rucola, Tomaten, Avocado, Tofu, Pickled Onions und Granatapfel-Drizzle.', 62),
  ('Sucuk Egg Bagel', 'bagels', 990, false, 'Avocado-Mash, Rucola, Tomate, Rührei, Sucuk und Sriracha-Mayo.', 63),
  ('Egg Bagel', 'bagels', 890, false, 'Frischkäse, Rucola, Tomate, Rührei, veganes Reibe-Topping und Maple-Mustard-Drizzle.', 64),
  ('Salmon Bagel', 'bagels', 1090, false, 'Frisch belegt mit Frischkäse, Rucola, Gurkensalat, Lachs, Pickled Onions und Dill-Dattelsenf-Dressing. Auch mit veganem Lachs.', 65),
  ('Süßkartoffel-Pommes mit Dip', 'pommes', 690, false, 'Dip deiner Wahl: Trüffelcreme, Kräuterquark, vegane Mayo oder Ketchup.', 66),
  ('Classic French Toast', 'sweets', 1250, false, 'Goldbraun gebraten, serviert mit hausgemachter Vanille-Mascarpone-Creme, Beerenkompott, frischen Beeren, karamellisierter Banane, Bio-Ahornsirup und Brownie-Crumble.', 67),
  ('Classy Berry Pancakes', 'sweets', 1190, false, 'Goldbraun gebackene Pancakes mit Beeren, cremiger Soja-Vanillecreme und Bio-Ahornsirup.', 68),
